import pandas as pd


def _is_null(v):
    try:
        return pd.isna(v)
    except (TypeError, ValueError):
        return v is None


def _neq(a, b):
    """NULL-aware inequality: NULL vs NULL -> not changed; NULL vs value -> changed."""
    a_null = _is_null(a)
    b_null = _is_null(b)
    if a_null and b_null:
        return False
    if a_null or b_null:
        return True
    return a != b


def _get_input(inputs: dict, *candidates):
    """Resolve an input dataframe by trying several candidate names,
    case-insensitively, falling back to substring matching."""
    # exact match first
    for c in candidates:
        if c in inputs:
            return inputs[c]
    # case-insensitive exact match
    lower_map = {k.lower(): k for k in inputs.keys()}
    for c in candidates:
        if c.lower() in lower_map:
            return inputs[lower_map[c.lower()]]
    # substring match
    for c in candidates:
        for k in inputs.keys():
            if c.lower() in k.lower():
                return inputs[k]
    raise KeyError(f"None of candidates {candidates} found in inputs keys {list(inputs.keys())}")


def run(inputs: dict) -> dict:
    dim_in = _get_input(inputs, 'DIM_ACCT', 'dim_acct')
    stg_in = _get_input(inputs, 'STG_ACCT', 'stg_acct')

    dim = dim_in.copy()
    stg = stg_in.copy()

    # Normalize is_current to int
    if 'is_current' in dim.columns:
        dim['is_current'] = dim['is_current'].astype(int)

    # ---- Step 1: Dedup STG_ACCT to latest per acct_id by update_date,
    # ties broken by greater (email, tier) lexicographic pair ----
    if len(stg) > 0:
        stg_sorted = stg.sort_values(
            by=['update_date', 'email', 'tier'],
            na_position='last',
            kind='mergesort'
        )
        stg_dedup = stg_sorted.groupby('acct_id', as_index=False, sort=False).tail(1)
    else:
        stg_dedup = stg.copy()

    # ---- Prepare mutable working set of DIM_ACCT rows ----
    dim = dim.reset_index(drop=True)
    rows = dim.to_dict('records')

    def get_current_idx(acct_id):
        for i, r in enumerate(rows):
            if r['acct_id'] == acct_id and int(r.get('is_current', 0)) == 1:
                return i
        return None

    new_rows = []

    for _, s in stg_dedup.iterrows():
        acct_id = s['acct_id']
        s_email = s['email']
        s_tier = s['tier']
        s_update_date = s['update_date']

        idx = get_current_idx(acct_id)

        if idx is None:
            # No current row -> insert new current version
            new_rows.append({
                'acct_id': acct_id,
                'email': s_email,
                'tier': s_tier,
                'eff_start_date': s_update_date,
                'eff_end_date': pd.NaT,
                'is_current': 1,
            })
        else:
            c = rows[idx]
            old_email = c.get('email')
            tier_changed = _neq(c.get('tier'), s_tier)
            email_changed = _neq(old_email, s_email)

            if tier_changed:
                # Expire current row (Type-2 versioning)
                rows[idx]['eff_end_date'] = s_update_date
                rows[idx]['is_current'] = 0

                new_rows.append({
                    'acct_id': acct_id,
                    'email': s_email,
                    'tier': s_tier,
                    'eff_start_date': s_update_date,
                    'eff_end_date': pd.NaT,
                    'is_current': 1,
                })

            if email_changed:
                # Type-1 retro-overwrite: update ALL rows of this acct_id
                # (history and current) including the newly inserted row.
                for r in rows:
                    if r['acct_id'] == acct_id:
                        r['email'] = s_email
                for r in new_rows:
                    if r['acct_id'] == acct_id:
                        r['email'] = s_email

    all_rows = rows + new_rows

    cols = ['acct_id', 'email', 'tier', 'eff_start_date', 'eff_end_date', 'is_current']
    if len(all_rows) == 0:
        out = pd.DataFrame(columns=cols)
    else:
        out = pd.DataFrame(all_rows, columns=cols)

    if 'is_current' in out.columns:
        out['is_current'] = out['is_current'].astype(int)

    return {'dim_acct_out': out}
